insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Impedimento, perturbação ou fraude de concorrência: impedir, perturbar ou fraudar concorrência pública ou venda em hasta pública, promovida pela administração federal, estadual ou municipal, ou por entidade paraestatal; afastar ou procurar afastar concorrente ou licitante, por meio de violência, grave ameaça, fraude ou oferecimento de vantagem. Pena: detenção de seis meses a dois anos, ou multa, além da pena correspondente à violência. Incorre na mesma pena quem se abstém de concorrer ou licitar, em razão da vantagem oferecida.', '["Impedir, perturbar ou fraudar concorrência pública ou hasta pública.","Afastar ou procurar afastar concorrente por violência, grave ameaça, fraude ou oferecimento de vantagem.","Detenção de seis meses a dois anos, ou multa, além da pena da violência.","Parágrafo único: quem se abstém de concorrer em razão da vantagem."]'::jsonb, '["Quem aceita a vantagem para não concorrer também responde."]'::jsonb, 'Pagar a um concorrente para que não participe da licitação.', '["Assertiva que isenta quem se abstém de licitar em razão de vantagem erra: ele incorre na mesma pena."]'::jsonb, '[]'::jsonb, '["Art. 337-F"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-335'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Inutilização de edital ou de sinal: rasgar ou, de qualquer forma, inutilizar ou conspurcar edital afixado por ordem de funcionário público; violar ou inutilizar selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto. Pena: detenção de um mês a um ano, ou multa.', '["Rasgar, inutilizar ou conspurcar edital afixado por ordem de funcionário.","Violar ou inutilizar selo ou sinal de identificação ou fechamento.","Detenção de um mês a um ano, ou multa."]'::jsonb, '["O edital deve ter sido afixado por ordem de funcionário público."]'::jsonb, 'Arrancar edital afixado na porta do fórum.', '["Assertiva que aplica o art. 336 a qualquer cartaz particular erra: o edital deve ser afixado por ordem de funcionário público."]'::jsonb, '[]'::jsonb, '["Art. 337"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-336'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Subtração ou inutilização de livro ou documento: subtrair, ou inutilizar, total ou parcialmente, livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público. Pena: reclusão de dois a cinco anos, se o fato não constitui crime mais grave.', '["Subtrair ou inutilizar livro oficial, processo ou documento sob custódia.","Custódia de funcionário ou de particular em serviço público.","Reclusão de dois a cinco anos.","Subsidiário."]'::jsonb, '["Diferença para o art. 314: lá, o agente tem a guarda em razão do cargo; aqui, o agente é terceiro que subtrai ou inutiliza."]'::jsonb, 'Particular subtrai processo que está sob custódia do cartório.', '["Assertiva que exige que o autor seja o próprio custodiante do documento erra: o art. 337 é crime comum."]'::jsonb, '[]'::jsonb, '["Art. 314"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-337'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sonegação de contribuição previdenciária: suprimir ou reduzir contribuição social previdenciária e qualquer acessório, omitindo de folha de pagamento ou de documento de informações segurados que prestem serviços; deixando de lançar mensalmente na contabilidade as quantias descontadas dos segurados ou devidas pelo empregador; ou omitindo, total ou parcialmente, receitas, lucros, remunerações pagas ou demais fatos geradores. Pena: reclusão de 2 a 5 anos e multa. É extinta a punibilidade se o agente, espontaneamente, declara e confessa as contribuições, importâncias ou valores e presta as informações devidas à previdência social antes do início da ação fiscal. É facultado ao juiz deixar de aplicar a pena ou aplicar somente a multa nas hipóteses previstas em lei.', '["Suprimir ou reduzir contribuição previdenciária mediante omissão em folha, contabilidade ou receitas.","Reclusão de 2 a 5 anos e multa.","§1º: declaração e confissão espontâneas antes da ação fiscal extinguem a punibilidade.","§2º: possibilidade de perdão judicial ou só multa."]'::jsonb, '["A espontaneidade deve ser ANTES do início da ação fiscal.","Crime material: exige a supressão ou redução do tributo."]'::jsonb, 'Empresa omite empregados da folha para reduzir contribuição previdenciária.', '["Assertiva que extingue a punibilidade pela confissão depois do início da ação fiscal erra: deve ser antes."]'::jsonb, '[]'::jsonb, '["Art. 168-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-337-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Corrupção ativa em transação comercial internacional: prometer, oferecer ou dar, direta ou indiretamente, vantagem indevida a funcionário público estrangeiro, ou a terceira pessoa, para determiná-lo a praticar, omitir ou retardar ato de ofício relacionado à transação comercial internacional. Pena: reclusão de 1 a 8 anos e multa. A pena é aumentada de 1/3, se, em razão da vantagem ou promessa, o funcionário público estrangeiro retarda ou omite o ato de ofício, ou o pratica infringindo dever funcional.', '["Prometer, oferecer ou dar vantagem indevida a funcionário público estrangeiro (ou a terceiro).","Fim relacionado a transação comercial internacional.","Reclusão de 1 a 8 anos e multa.","Parágrafo único: aumento de 1/3."]'::jsonb, '["Aqui o núcleo inclui DAR (diferente do art. 333)."]'::jsonb, 'Empresário oferece vantagem a funcionário estrangeiro para obter contrato internacional.', '["Assertiva que limita o art. 337-B a funcionário público nacional erra: o tipo trata de funcionário público estrangeiro."]'::jsonb, '[]'::jsonb, '["Art. 333","Art. 337-D"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-337-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tráfico de influência em transação comercial internacional: solicitar, exigir, cobrar ou obter, para si ou para outrem, direta ou indiretamente, vantagem ou promessa de vantagem a pretexto de influir em ato praticado por funcionário público estrangeiro no exercício de suas funções, relacionado a transação comercial internacional. Pena: reclusão de 2 a 5 anos e multa. A pena é aumentada da metade, se o agente alega ou insinua que a vantagem é também destinada a funcionário estrangeiro.', '["Solicitar, exigir, cobrar ou obter vantagem a pretexto de influir em ato de funcionário estrangeiro.","Transação comercial internacional.","Reclusão de 2 a 5 anos e multa.","Parágrafo único: aumento da metade."]'::jsonb, '["Paralelo ao art. 332, com funcionário público estrangeiro."]'::jsonb, 'Pessoa cobra dinheiro dizendo influenciar funcionário estrangeiro em contrato internacional.', '["Assertiva que aplica o art. 337-C a ato de funcionário público nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 332","Art. 337-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-337-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

