insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Contratação inidônea: admitir à licitação empresa ou profissional declarado inidôneo. Pena: reclusão de 1 a 3 anos e multa. Celebrar contrato com empresa ou profissional declarado inidôneo: reclusão de 3 a 6 anos e multa. Incide na pena do caput aquele que, declarado inidôneo, venha a participar de licitação, e na pena do §1º aquele que, declarado inidôneo, venha a contratar com a Administração Pública.', '["Caput: admitir à licitação empresa ou profissional declarado inidôneo (1 a 3 anos).","§1º: celebrar contrato com inidôneo (3 a 6 anos).","§2º: o próprio inidôneo que participa de licitação ou contrata."]'::jsonb, '["O §2º alcança também o próprio declarado inidôneo."]'::jsonb, 'Empresa declarada inidônea participa de nova licitação.', '["Assertiva que pune só o agente público no art. 337-M erra: o §2º alcança o declarado inidôneo."]'::jsonb, '[]'::jsonb, '["Art. 337-E"]'::jsonb, 'under_review', 'claude'
