insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Impedimento indevido: obstar, impedir ou dificultar injustamente a inscrição de qualquer interessado nos registros cadastrais ou promover indevidamente a alteração, a suspensão ou o cancelamento de registro do inscrito. Pena: reclusão de 6 meses a 2 anos e multa.', '["Obstar, impedir ou dificultar injustamente a inscrição em registros cadastrais.","Ou promover indevidamente alteração, suspensão ou cancelamento de registro.","Reclusão de 6 meses a 2 anos e multa."]'::jsonb, '["Exige que o ato seja injusto ou indevido."]'::jsonb, 'Servidor cancela, sem motivo legal, o registro cadastral de um fornecedor.', '["Assertiva que pune qualquer recusa de inscrição, ainda que justa, erra."]'::jsonb, '[]'::jsonb, '["Art. 337-M"]'::jsonb, 'under_review', 'claude'
