insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Omissão grave de dado ou de informação por projetista: omitir, modificar ou entregar à Administração Pública levantamento cadastral ou condição de contorno em relevante dissonância com a realidade, em frustração ao caráter competitivo da licitação ou em detrimento da seleção da proposta mais vantajosa, em contratação para a elaboração de projeto básico, projeto executivo ou anteprojeto, em diálogo competitivo ou em procedimento de manifestação de interesse. Pena: reclusão de 6 meses a 3 anos e multa. Condição de contorno: informações e levantamentos suficientes e necessários para a definição da solução de projeto e dos preços pelo licitante, incluídos sondagens, topografia, estudos de demanda e condições ambientais. Se o crime é praticado com o fim de obter benefício, direto ou indireto, próprio ou de outrem, aplica-se em dobro a pena do caput.', '["Omitir, modificar ou entregar levantamento cadastral ou condição de contorno em relevante dissonância com a realidade.","Em contratação de projeto básico, executivo ou anteprojeto, diálogo competitivo ou manifestação de interesse.","Reclusão de 6 meses a 3 anos e multa.","§1º: conceito de condição de contorno.","§2º: fim de benefício próprio ou alheio: pena em dobro."]'::jsonb, '["A dissonância com a realidade deve ser RELEVANTE.","O fim de benefício dobra a pena."]'::jsonb, 'Projetista entrega levantamento topográfico muito diferente da realidade, frustrando a competição.', '["Assertiva que fixa a pena em dobro para qualquer caso do art. 337-O erra: o dobro depende do fim de benefício."]'::jsonb, '[]'::jsonb, '["Art. 337-F"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-337-o'
