insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Multa nos crimes contra licitações e contratos: a pena de multa cominada aos crimes previstos neste Capítulo seguirá a metodologia de cálculo prevista neste Código e não poderá ser inferior a 2% do valor do contrato licitado ou celebrado com contratação direta.', '["Multa segue a metodologia de cálculo do Código Penal.","Piso: não inferior a 2% do valor do contrato licitado ou celebrado por contratação direta."]'::jsonb, '["O piso é de 2% do valor do contrato."]'::jsonb, 'Em fraude a contrato de valor elevado, a multa não pode ficar abaixo de 2% do contrato.', '["Assertiva que fixa o piso da multa em 5% do contrato erra: é de 2%."]'::jsonb, '[]'::jsonb, '["Art. 337-E","Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-337-p'
