insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Descumprimento de medidas protetivas de urgência: descumprir decisão judicial que defere medidas protetivas de urgência. Pena: reclusão de 2 a 5 anos e multa. A configuração do crime independe da competência civil ou criminal do juiz que deferiu as medidas. Na prisão em flagrante, apenas a autoridade judicial pode conceder fiança. O disposto não exclui a aplicação de outras sanções cabíveis.', '["Descumprir decisão judicial que defere medidas protetivas de urgência.","Reclusão de 2 a 5 anos e multa.","§1º: independe da competência civil ou criminal do juiz.","§2º: em flagrante, só a autoridade judicial concede fiança.","§3º: não exclui outras sanções."]'::jsonb, '["A fiança no flagrante só pode ser concedida pelo JUIZ, não pelo delegado."]'::jsonb, 'Agressor descumpre decisão que o proíbe de se aproximar da vítima.', '["Assertiva que permite ao delegado conceder fiança no art. 338-A erra: apenas a autoridade judicial."]'::jsonb, '[]'::jsonb, '["Lei nº 11.340, de 2006"]'::jsonb, 'under_review', 'claude'
