insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Denunciação caluniosa: dar causa à instauração de inquérito policial, de procedimento investigatório criminal, de processo judicial, de processo administrativo disciplinar, de inquérito civil ou de ação de improbidade administrativa contra alguém, imputando-lhe crime, infração ético-disciplinar ou ato ímprobo de que o sabe inocente. Pena: reclusão de dois a oito anos e multa. A pena é aumentada de sexta parte se o agente se serve de anonimato ou de nome suposto. É diminuída de metade se a imputação é de prática de contravenção.', '["Dar causa à instauração de procedimento contra alguém que sabe inocente.","Reclusão de dois a oito anos e multa.","§1º: anonimato ou nome suposto: aumento de sexta parte.","§2º: imputação de contravenção: diminuição de metade."]'::jsonb, '["Exige que o agente SAIBA da inocência da vítima (dolo direto).","A imputação de contravenção reduz a pena."]'::jsonb, 'Pessoa acusa falsamente alguém de crime para que seja instaurado inquérito, sabendo que é inocente.', '["Assertiva que admite dolo eventual na denunciação caluniosa erra: exige o conhecimento da inocência."]'::jsonb, '[]'::jsonb, '["Art. 138","Art. 340"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-339'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comunicação falsa de crime ou de contravenção: provocar a ação de autoridade, comunicando-lhe a ocorrência de crime ou de contravenção que sabe não se ter verificado. Pena: detenção de um a seis meses, ou multa.', '["Provocar a ação de autoridade comunicando crime ou contravenção que sabe não ter ocorrido.","Detenção de um a seis meses, ou multa."]'::jsonb, '["Não há imputação a pessoa determinada (diferença da denunciação caluniosa)."]'::jsonb, 'Ligar para a polícia informando assalto inexistente.', '["Assertiva que exige imputação a pessoa determinada no art. 340 erra."]'::jsonb, '[]'::jsonb, '["Art. 339"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-340'
