insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Autoacusação falsa: acusar-se, perante a autoridade, de crime inexistente ou praticado por outrem. Pena: detenção de três meses a dois anos, ou multa.', '["Acusar-se de crime inexistente ou praticado por outra pessoa.","Perante a autoridade.","Detenção de três meses a dois anos, ou multa."]'::jsonb, '["Crime de quem assume falsamente a autoria."]'::jsonb, 'Pessoa se apresenta como autora de crime cometido por seu filho.', '["Assertiva que aplica o art. 341 à acusação falsa contra terceiro erra: isso seria denunciação caluniosa."]'::jsonb, '[]'::jsonb, '["Art. 339"]'::jsonb, 'under_review', 'claude'
