insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falso testemunho ou falsa perícia: fazer afirmação falsa, ou negar ou calar a verdade como testemunha, perito, contador, tradutor ou intérprete em processo judicial, ou administrativo, inquérito policial, ou em juízo arbitral. As penas aumentam-se de um sexto a um terço, se o crime é praticado mediante suborno ou com o fim de obter prova destinada a produzir efeito em processo penal, ou em processo civil em que for parte entidade da administração pública direta ou indireta. O fato deixa de ser punível se, antes da sentença no processo em que ocorreu o ilícito, o agente se retrata ou declara a verdade.', '["Fazer afirmação falsa, negar ou calar a verdade como testemunha, perito, contador, tradutor ou intérprete.","Em processo judicial ou administrativo, inquérito policial ou juízo arbitral.","§1º: aumento de um sexto a um terço (suborno; processo penal; processo civil com entidade da administração).","§2º: retratação antes da sentença torna o fato não punível."]'::jsonb, '["Crime PRÓPRIO.","A retratação até a sentença extingue a punibilidade do fato."]'::jsonb, 'Testemunha mente em audiência, mas se retrata antes da sentença: fato não punível.', '["Assertiva que admite a retratação após a sentença, para afastar a punição, erra: deve ser antes da sentença."]'::jsonb, '[]'::jsonb, '["Art. 343"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-342'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Corrupção ativa de testemunha ou perito: dar, oferecer ou prometer dinheiro ou qualquer outra vantagem a testemunha, perito, contador, tradutor ou intérprete, para fazer afirmação falsa, negar ou calar a verdade em depoimento, perícia, cálculos, tradução ou interpretação.', '["Dar, oferecer ou prometer dinheiro ou vantagem a testemunha, perito, contador, tradutor ou intérprete.","Para fazer afirmação falsa, negar ou calar a verdade."]'::jsonb, '["Quem corrompe a testemunha responde por este artigo; a testemunha, pelo art. 342."]'::jsonb, 'Oferecer dinheiro a uma testemunha para que minta em juízo.', '["Assertiva que absorve a corrupção da testemunha pelo falso testemunho erra: são crimes distintos."]'::jsonb, '[]'::jsonb, '["Art. 342"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-343'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Coação no curso do processo: usar de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em processo judicial, policial ou administrativo, ou em juízo arbitral. Pena: reclusão de um a quatro anos e multa, além da pena correspondente à violência. A pena aumenta-se de 1/3 até a metade se o processo envolver crime contra a dignidade sexual.', '["Violência ou grave ameaça para favorecer interesse próprio ou alheio.","Contra autoridade, parte ou quem intervém no processo.","Reclusão de um a quatro anos e multa, além da pena da violência.","Parágrafo único: processo de crime contra a dignidade sexual: aumento de 1/3 até a metade."]'::jsonb, '["Exige que a coação seja no curso de processo (judicial, policial, administrativo ou arbitral)."]'::jsonb, 'Ameaçar a testemunha para que altere seu depoimento.', '["Assertiva que dispensa a violência ou grave ameaça na coação no curso do processo erra."]'::jsonb, '[]'::jsonb, '["Art. 342"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-344'
