insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exercício arbitrário das próprias razões: fazer justiça pelas próprias mãos, para satisfazer pretensão, embora legítima, salvo quando a lei o permite. Pena: detenção de quinze dias a um mês, ou multa, além da pena correspondente à violência. Se não há emprego de violência, somente se procede mediante queixa.', '["Fazer justiça pelas próprias mãos para satisfazer pretensão, ainda que legítima.","Detenção de quinze dias a um mês, ou multa, além da pena da violência.","Parágrafo único: sem violência, ação por queixa."]'::jsonb, '["A pretensão pode ser LEGÍTIMA.","Sem violência: ação privada."]'::jsonb, 'Credor invade a casa do devedor e toma um bem para pagar a dívida.', '["Assertiva que exige pretensão ilegítima no art. 345 erra: o tipo admite pretensão legítima."]'::jsonb, '[]'::jsonb, '["Art. 346"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-345'
