insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraude processual: inovar artificiosamente, na pendência de processo civil ou administrativo, o estado de lugar, de coisa ou de pessoa, com o fim de induzir a erro o juiz ou o perito. Pena: detenção de três meses a dois anos e multa. Se a inovação se destina a produzir efeito em processo penal, ainda que não iniciado, as penas aplicam-se em dobro.', '["Inovar artificiosamente o estado de lugar, coisa ou pessoa.","Na pendência de processo civil ou administrativo.","Fim de induzir a erro o juiz ou o perito.","Detenção de três meses a dois anos e multa.","Parágrafo único: efeito em processo penal, ainda que não iniciado: pena em dobro."]'::jsonb, '["Em processo penal, mesmo que ainda NÃO iniciado, a pena é em dobro."]'::jsonb, 'Alterar a cena de um crime antes da perícia para induzir o perito a erro.', '["Assertiva que exige processo penal já iniciado para o dobro da pena erra: vale ainda que não iniciado."]'::jsonb, '[]'::jsonb, '["Art. 342"]'::jsonb, 'under_review', 'claude'
