insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Favorecimento pessoal: auxiliar a subtrair-se à ação de autoridade pública autor de crime a que é cominada pena de reclusão. Pena: detenção de um a seis meses e multa. Se ao crime não é cominada pena de reclusão: detenção de quinze dias a três meses e multa. Se quem presta o auxílio é ascendente, descendente, cônjuge ou irmão do criminoso, fica isento de pena.', '["Auxiliar autor de crime a subtrair-se à ação da autoridade.","Crime com pena de reclusão: detenção de um a seis meses e multa.","Crime sem pena de reclusão: detenção de quinze dias a três meses e multa.","§2º: isenção para ascendente, descendente, cônjuge ou irmão."]'::jsonb, '["A pena depende de o crime auxiliado ter, ou não, pena de reclusão.","A isenção familiar não alcança companheiro e outros parentes (a doutrina discute)."]'::jsonb, 'Esconder em sua casa um foragido autor de crime punido com reclusão.', '["Assertiva que pune o irmão que esconde o criminoso erra: ele fica isento de pena."]'::jsonb, '[]'::jsonb, '["Art. 349"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-348'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Favorecimento real: prestar a criminoso, fora dos casos de coautoria ou de receptação, auxílio destinado a tornar seguro o proveito do crime. Pena: detenção de um a seis meses e multa.', '["Prestar auxílio ao criminoso para tornar seguro o proveito do crime.","Fora dos casos de coautoria ou receptação.","Detenção de um a seis meses e multa."]'::jsonb, '["Subsidiário em relação à coautoria e à receptação.","Auxilia o PROVEITO, e não a pessoa (diferença do art. 348)."]'::jsonb, 'Guardar o dinheiro do roubo para que o criminoso não seja alcançado.', '["Assertiva que confunde favorecimento real com pessoal erra: o real auxilia o proveito do crime."]'::jsonb, '[]'::jsonb, '["Art. 348","Art. 180"]'::jsonb, 'under_review', 'claude'
