insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fuga de pessoa presa ou submetida a medida de segurança: promover ou facilitar a fuga de pessoa legalmente presa ou submetida a medida de segurança detentiva. Pena: detenção de seis meses a dois anos. Se o crime é praticado a mão armada, ou por mais de uma pessoa, ou mediante arrombamento: reclusão de dois a seis anos. Se há emprego de violência contra pessoa, aplica-se também a pena da violência. Se praticado por pessoa sob cuja custódia ou guarda está o preso ou o internado: reclusão de um a quatro anos. No caso de culpa do funcionário incumbido da custódia ou guarda: detenção de três meses a um ano, ou multa.', '["Promover ou facilitar a fuga de pessoa legalmente presa ou em medida de segurança detentiva.","Detenção de seis meses a dois anos.","§1º: mão armada, mais de uma pessoa ou arrombamento: reclusão de dois a seis anos.","§2º: violência contra pessoa: também a pena da violência.","§3º: agente é o custodiante: reclusão de um a quatro anos.","§4º: culpa do funcionário: detenção de três meses a um ano, ou multa."]'::jsonb, '["Quem promove a fuga do preso responde; o preso que foge sem violência não comete crime (mas falta disciplinar).","Há modalidade culposa para o funcionário custodiante."]'::jsonb, 'Agente penitenciário facilita a fuga de um preso sob sua guarda: reclusão de um a quatro anos.', '["Assertiva que pune o preso que foge sem violência pelo art. 351 erra: o tipo pune quem promove ou facilita a fuga."]'::jsonb, '[]'::jsonb, '["Art. 352"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-351'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Evasão mediante violência contra a pessoa: evadir-se ou tentar evadir-se o preso ou o indivíduo submetido a medida de segurança detentiva, usando de violência contra a pessoa. Pena: detenção de três meses a um ano, além da pena correspondente à violência.', '["Preso ou internado se evade ou tenta evadir-se usando violência contra a pessoa.","Detenção de três meses a um ano, além da pena da violência."]'::jsonb, '["Só há crime se houver VIOLÊNCIA CONTRA A PESSOA; a fuga simples não é crime."]'::jsonb, 'Preso agride o agente para fugir.', '["Assertiva que pune a evasão simples, sem violência, erra: não é crime."]'::jsonb, '[]'::jsonb, '["Art. 351"]'::jsonb, 'under_review', 'claude'
