select u.id, u.content_sha256, 'Arrebatamento de preso: arrebatar preso, a fim de maltratá-lo, do poder de quem o tenha sob custódia ou guarda. Pena: reclusão de um a quatro anos, além da pena correspondente à violência.', '["Arrebatar preso do poder de quem o tem sob custódia ou guarda.","Fim de maltratá-lo.","Reclusão de um a quatro anos, além da pena da violência."]'::jsonb, '["Exige o fim específico de MALTRATAR o preso."]'::jsonb, 'Grupo retira o preso da delegacia para linchá-lo.', '["Assertiva que dispensa o fim de maltratar o preso erra."]'::jsonb, '[]'::jsonb, '["Art. 351"]'::jsonb, 'under_review', 'claude'
