insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Patrocínio infiel: trair, na qualidade de advogado ou procurador, o dever profissional, prejudicando interesse cujo patrocínio, em juízo, lhe é confiado. Pena: detenção de seis meses a três anos e multa. Tergiversação (patrocínio simultâneo): incorre na pena o advogado ou procurador judicial que defende na mesma causa, simultânea ou sucessivamente, partes contrárias.', '["Trair o dever profissional, prejudicando interesse que lhe é confiado em juízo.","Detenção de seis meses a três anos e multa.","Parágrafo único: defender, na mesma causa, partes contrárias, simultânea ou sucessivamente."]'::jsonb, '["Crime próprio do advogado ou procurador.","O parágrafo único é a tergiversação."]'::jsonb, 'Advogado atua para a parte contrária na mesma causa.', '["Assertiva que exige que a defesa de partes contrárias seja simultânea na tergiversação erra: pode ser sucessiva."]'::jsonb, '[{"termo":"Tergiversação","significado":"Defender partes contrárias na mesma causa."}]'::jsonb, '["Art. 356"]'::jsonb, 'under_review', 'claude'
