select u.id, u.content_sha256, 'Sonegação de papel ou objeto de valor probatório: inutilizar, total ou parcialmente, ou deixar de restituir autos, documento ou objeto de valor probatório, que recebeu na qualidade de advogado ou procurador. Pena: detenção de seis meses a três anos e multa.', '["Inutilizar ou deixar de restituir autos, documento ou objeto de valor probatório.","Recebidos na qualidade de advogado ou procurador.","Detenção de seis meses a três anos e multa."]'::jsonb, '["Crime próprio do advogado ou procurador."]'::jsonb, 'Advogado retira os autos do cartório e não os devolve.', '["Assertiva que aplica o art. 356 a qualquer pessoa erra: é crime próprio de advogado ou procurador."]'::jsonb, '[]'::jsonb, '["Art. 355"]'::jsonb, 'under_review', 'claude'
