insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exploração de prestígio: solicitar ou receber dinheiro ou qualquer outra utilidade, a pretexto de influir em juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha. Pena: reclusão de um a cinco anos e multa. As penas aumentam-se de um terço se o agente alega ou insinua que o dinheiro ou utilidade também se destina a qualquer das pessoas referidas.', '["Solicitar ou receber dinheiro ou utilidade a pretexto de influir em pessoas ligadas à Justiça.","Reclusão de um a cinco anos e multa.","Parágrafo único: alegar ou insinuar destinação a essas pessoas: aumento de um terço."]'::jsonb, '["Diferença para o art. 332: aqui o pretexto é influir em pessoas da JUSTIÇA (juiz, jurado, MP etc.)."]'::jsonb, 'Pessoa cobra dinheiro dizendo ter influência sobre o juiz da causa.', '["Assertiva que confunde exploração de prestígio com tráfico de influência erra: aquela envolve pessoas ligadas à Justiça."]'::jsonb, '[]'::jsonb, '["Art. 332"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-357'
