select u.id, u.content_sha256, 'Violência ou fraude em arrematação judicial: impedir, perturbar ou fraudar arrematação judicial; afastar ou procurar afastar concorrente ou licitante, por meio de violência, grave ameaça, fraude ou oferecimento de vantagem. Pena: detenção de dois meses a um ano, ou multa, além da pena correspondente à violência.', '["Impedir, perturbar ou fraudar arrematação judicial.","Afastar ou procurar afastar concorrente por violência, grave ameaça, fraude ou vantagem.","Detenção de dois meses a um ano, ou multa, além da pena da violência."]'::jsonb, '["Trata de arrematação JUDICIAL."]'::jsonb, 'Ameaçar outro participante para que desista de arrematar bem em leilão judicial.', '["Assertiva que aplica o art. 358 a licitação administrativa erra: o tipo trata de arrematação judicial."]'::jsonb, '[]'::jsonb, '["Art. 335"]'::jsonb, 'under_review', 'claude'
