select u.id, u.content_sha256, 'Desobediência a decisão judicial sobre perda ou suspensão de direito: exercer função, atividade, direito, autoridade ou múnus, de que foi suspenso ou privado por decisão judicial. Pena: detenção de três meses a dois anos, ou multa.', '["Exercer função, atividade, direito, autoridade ou múnus de que foi suspenso ou privado por decisão judicial.","Detenção de três meses a dois anos, ou multa."]'::jsonb, '["Depende de DECISÃO JUDICIAL de suspensão ou privação."]'::jsonb, 'Profissional suspenso por decisão judicial continua exercendo a atividade.', '["Assertiva que aplica o art. 359 à suspensão decidida só em âmbito administrativo erra: exige decisão judicial."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
