insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Contratação de operação de crédito: ordenar, autorizar ou realizar operação de crédito, interno ou externo, sem prévia autorização legislativa. Pena: reclusão de 1 a 2 anos. Incide na mesma pena quem ordena, autoriza ou realiza operação de crédito com inobservância de limite, condição ou montante estabelecido em lei ou em resolução do Senado Federal, ou quando o montante da dívida consolidada ultrapassa o limite máximo autorizado por lei.', '["Ordenar, autorizar ou realizar operação de crédito sem prévia autorização legislativa.","Reclusão de 1 a 2 anos.","Parágrafo único: inobservância de limite, condição ou montante; dívida consolidada acima do limite."]'::jsonb, '["Crimes contra as finanças públicas (Lei de Responsabilidade Fiscal)."]'::jsonb, 'Gestor contrata empréstimo sem a autorização legislativa necessária.', '["Assertiva que dispensa a autorização legislativa prévia no art. 359-A erra."]'::jsonb, '[]'::jsonb, '["Art. 359-B"]'::jsonb, 'under_review', 'claude'
