insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Espionagem: entregar a governo estrangeiro, a seus agentes, ou a organização criminosa estrangeira, em desacordo com determinação legal ou regulamentar, documento ou informação classificados como secretos ou ultrassecretos nos termos da lei, cuja revelação possa colocar em perigo a preservação da ordem constitucional ou a soberania nacional. Pena: reclusão de 3 a 12 anos. Incorre na mesma pena quem presta auxílio a espião, conhecendo essa circunstância, para subtraí-lo à ação da autoridade pública. Se o documento, dado ou informação é transmitido ou revelado com violação do dever de sigilo: reclusão de 6 a 15 anos. Facilitar a prática dos crimes do artigo mediante atribuição, fornecimento ou empréstimo de senha, ou de qualquer outra forma de acesso de pessoas não autorizadas a sistemas de informações: detenção de 1 a 4 anos.', '["Entregar a governo estrangeiro ou organização criminosa estrangeira documento ou informação secreta ou ultrassecreta.","Reclusão de 3 a 12 anos.","§1º: auxiliar espião, conhecendo a circunstância.","§2º: violação do dever de sigilo: reclusão de 6 a 15 anos.","§3º: facilitar mediante senha ou acesso de pessoas não autorizadas: detenção de 1 a 4 anos."]'::jsonb, '["O documento deve ser classificado como secreto ou ultrassecreto.","Violação do dever de sigilo eleva a pena."]'::jsonb, 'Servidor repassa a governo estrangeiro documento ultrassecreto.', '["Assertiva que aplica o art. 359-K a documento público comum erra: o tipo exige informação classificada como secreta ou ultrassecreta."]'::jsonb, '[]'::jsonb, '["Art. 359-I","Art. 325"]'::jsonb, 'under_review', 'claude'
